// The Cloudflare Worker in front of the static site. It does one thing: the
// redirects from next.config.ts, in the same order and with the same matching
// Next.js uses on Vercel. Everything else is a static file from out/.
//
// redirects.json is generated by scripts/cloudflare.mjs from
// .next/routes-manifest.json at build time. Cloudflare's own _redirects file
// isn't used because it lets a wildcard rule win over an exact one, which
// sent /head-spa-near/ayden-nc to /locations instead of /locations/ayden-nc.

import redirects from "./redirects.json";

const rules = redirects.map((r) => ({ ...r, re: new RegExp(r.regex) }));

const worker = {
  async fetch(request, env) {
    const url = new URL(request.url);

    for (const rule of rules) {
      const m = rule.re.exec(url.pathname);
      if (!m) continue;
      let to = rule.destination;
      rule.params.forEach((name, i) => {
        to = to.replaceAll(`:${name}`, m[i + 1] ?? "");
      });
      const target = new URL(to, url);
      if (!target.search) target.search = url.search;
      return Response.redirect(target.toString(), 301);
    }

    return env.ASSETS.fetch(request);
  },
};

export default worker;
